result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/etag-cache/src/client.mjs", "content": "import { get } from 'node:http';

/**
 * Create an ETag-aware HTTP caching GET client.
 *
 * Behavior:
 * - First `get(url)` fetches normally (miss) and stores `{ body, etag }` per URL.
 * - Subsequent `get(url)` sends `If-None-Match: <etag>`.
 *   - On 304 Not Modified, the cached body is returned (hit), no new body read.
 *   - On 200 OK with a new/updated ETag, the cache entry is replaced.
 */
export function createClient() {
  /** @type {Map<string, { body: string, etag: string | null }>} */
  const cache = new Map();

  /**
   * @param {string} url
   * @returns {Promise<{ body: string, status: number, fromCache: boolean, etag: string | null }>}
   */
  function get_(url) {
    const cached = cache.get(url);
    const headers = {};
    if (cached && cached.etag != null) {
      headers['If-None-Match'] = cached.etag;
    }

    return new Promise((resolve, reject) => {
      const req = get(url, { headers }, (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const body = Buffer.concat(chunks).toString('utf8');

          if (res.statusCode === 304 && cached) {
            // Not modified: serve from cache. Cache stays as-is.
            resolve({
              body: cached.body,
              status: 304,
              fromCache: true,
              etag: cached.etag,
            });
            return;
          }

          if (res.statusCode === 200) {
            const etag = res.headers.etag ?? null;
            cache.set(url, { body, etag });
            resolve({ body, status: 200, fromCache: false, etag });
            return;
          }

          reject(
            new Error(`Unexpected status ${res.statusCode} for ${url}`)
          );
        });
      });
      req.on('error', reject);
    });
  }

  return { get: get_ };
}
"})
