result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/etag-cache/test.mjs", "content": "import test from 'node:test';
import assert from 'node:assert/strict';

import { createClient } from './src/client.mjs';
import { createTestServer, listen, close } from './test/server.mjs';

test('etag-aware client caches across 304s and updates on change', async () => {
  const server = createTestServer();
  try {
    const base = await listen(server);
    const client = createClient();
    const url = `${base}/doc`;

    // First get: 200 miss, content fetched and cached.
    const first = await client.get(url);
    assert.equal(first.status, 200);
    assert.equal(first.fromCache, false);
    assert.equal(first.body, 'doc v1');
    assert.equal(first.etag, '"v-1"');

    // Second get: server answers 304 to matching If-None-Match,
    // client serves the cached body.
    const second = await client.get(url);
    assert.equal(second.status, 304);
    assert.equal(second.fromCache, true);
    assert.equal(second.body, 'doc v1');

    // Server request log must show exactly one 200 followed by one 304.
    const docLog = server.log.filter((e) => e.url === '/doc');
    assert.deepEqual(
      docLog.map((e) => e.status),
      [200, 304]
    );

    // Change the content on the server.
    const bumpRes = await fetch(`${base}/bump`, { method: 'POST' });
    const { version } = await bumpRes.json();
    assert.equal(version, 2);

    // Next get: server returns 200 with new body; cache is updated.
    const third = await client.get(url);
    assert.equal(third.status, 200);
    assert.equal(third.fromCache, false);
    assert.equal(third.body, 'doc v2');
    assert.equal(third.etag, '"v-2"');

    // A further get hits again via 304 against the new ETag.
    const fourth = await client.get(url);
    assert.equal(fourth.fromCache, true);
    assert.equal(fourth.body, 'doc v2');

    const statuses = server.log.filter((e) => e.url === '/doc').map((e) => e.status);
    assert.deepEqual(statuses, [200, 304, 200, 304]);
  } finally {
    await close(server);
  }
});

test('client works with a server on an ephemeral port', async () => {
  const server = createTestServer();
  try {
    const base = await listen(server);
    assert.match(base, /^http:\/\/127\.0\.0\.1:\d+$/);

    const client = createClient();
    const res = await client.get(`${base}/doc`);
    assert.equal(res.body, 'doc v1');
    assert.equal(res.etag, '"v-1"');
  } finally {
    await close(server);
  }
});
"})
