result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/etag-cache/test/server.mjs", "content": "import { createServer } from 'node:http';

/**
 * Test server:
 * - GET /doc  -> body `doc v<N>` with ETag derived from the version.
 *                Answers 304 Not Modified to a matching If-None-Match.
 * - POST /bump-> increments the version and returns `{ version }`.
 *
 * Every request is appended to `server.log` as
 * `{ method, url, status, ifNoneMatch }` so tests can distinguish
 * full 200 responses from 304 cache revalidations.
 */
export function createTestServer() {
  let version = 1;

  const server = createServer((req, res) => {
    const logEntry = { method: req.method, url: req.url, status: null, ifNoneMatch: req.headers['if-none-match'] ?? null };

    const finish = (status) => {
      logEntry.status = status;
      server.log.push(logEntry);
    };

    if (req.method === 'GET' && req.url === '/doc') {
      res.setHeader('ETag', `"v-${version}"`);
      if (req.headers['if-none-match'] === `"v-${version}"`) {
        res.statusCode = 304;
        finish(304);
        res.end();
        return;
      }
      finish(200);
      res.end(`doc v${version}`);
      return;
    }

    if (req.method === 'POST' && req.url === '/bump') {
      version += 1;
      res.setHeader('Content-Type', 'application/json');
      finish(200);
      res.end(JSON.stringify({ version }));
      return;
    }

    res.statusCode = 404;
    finish(404);
    res.end('not found');
  });

  server.log = [];
  return server;
}

/** Start the server on an ephemeral port; resolves to the base URL. */
export function listen(server) {
  return new Promise((resolve, reject) => {
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      resolve(`http://127.0.0.1:${port}`);
    });
    server.on('error', reject);
  });
}

/** Close the server cleanly; resolves once all connections are done. */
export function close(server) {
  return new Promise((resolve, reject) => {
    server.close((err) => (err ? reject(err) : resolve()));
  });
}
